package integration.scenario.webauthn;

import com.webauthn4j.WebAuthnManager;
import com.webauthn4j.converter.util.ObjectConverter;
import com.webauthn4j.data.RegistrationData;
import com.webauthn4j.data.RegistrationParameters;
import com.webauthn4j.data.RegistrationRequest;
import com.webauthn4j.data.client.Origin;
import com.webauthn4j.data.client.challenge.DefaultChallenge;
import com.webauthn4j.server.ServerProperty;
import com.webauthn4j.util.HexUtil;
import com.webauthn4j.verifier.exception.ConstraintViolationException;
import org.junit.jupiter.api.Test;

import java.util.Collections;

import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Verifies that ML-DSA credential registration is rejected with a meaningful error
 * on JDK versions that do not support ML-DSA (< 24).
 */
class MLDSARegistrationOnUnsupportedJDKTest {

    // ML-DSA-65 attestation object fixture (generated on JDK 24+)
    static final byte[] ATTESTATION_OBJECT = HexUtil.decode("");
    static final byte[] CLIENT_DATA_JSON = HexUtil.decode("7B2274797065223A22776562617574686E2E637265617465222C226368616C6C656E6765223A22317948534B62517452647969714E4B5066537A495A41222C226F726967696E223A22687474703A2F2F6578616D706C652E636F6D227D");

    @Test
    void registration_should_throw_ConstraintViolationException() {
        ObjectConverter objectConverter = new ObjectConverter();
        WebAuthnManager webAuthnManager = WebAuthnManager.createNonStrictWebAuthnManager(objectConverter);

        RegistrationRequest registrationRequest = new RegistrationRequest(
                ATTESTATION_OBJECT,
                CLIENT_DATA_JSON,
                Collections.emptySet()
        );

        ServerProperty serverProperty = ServerProperty.builder()
                .origin(new Origin("http://example.com"))
                .rpId("example.com")
                .challenge(new DefaultChallenge(HexUtil.decode("D721D229B42D45DCA2A8D28F7D2CC864")))
                .build();

        RegistrationParameters registrationParameters = new RegistrationParameters(
                serverProperty,
                null,
                false,
                true
        );

        assertThatThrownBy(() -> webAuthnManager.verify(registrationRequest, registrationParameters))
                .isInstanceOf(ConstraintViolationException.class)
                .hasMessage("ML-DSA is not supported on this runtime. JDK 24 or later is required.");
    }
}
